use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn all_greater_than(v: Vec<i8>, s: i8) -> bool
    decreases v.len(),
{
    if v.len() == 0 {
        true
    } else {
        v[0] > s && all_greater_than(v.subrange(1..), s)
    }
}

fn solve(n: i8, s: i8, a: Vec<i8>) -> (result: i8)
    requires
        n >= 1,
        s >= 1,
        a@.len() == n as nat,
        n <= 3000,
        s <= 3000,
        forall|i: int| 0 <= i < a@.len() ==> a[i] >= 1 && a[i] <= 3000,
    ensures
        // Result is 0 or 1
        result == 0 || result == 1,
        // If n = 1 and the single element equals s, result = 1
        (n == 1 && a@.len() == 1 && a[0] == s) ==> result == 1,
        // Otherwise, result = 0
        (n != 1 || a@.len() != 1 || a[0] != s) ==> result == 0,
        // If all elements > s, result = 0
        all_greater_than(a, s) ==> result == 0,
{
    // Check if all elements are greater than s
    let mut all_greater = true;
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            all_greater == all_greater_than(a.subrange(0, i), s),
        decreases a.len() - i,
    {
        if a[i] <= s {
            all_greater = false;
        }
        i = i + 1;
    }
    
    if all_greater {
        return 0;
    }
    
    // Check the main condition
    if n == 1 && a.len() == 1 && a[0] == s {
        1
    } else {
        0
    }
}

}
